const canvas = document.getElementById('output-canvas');
        const ctx = canvas.getContext('2d');
        const uploadUI = document.getElementById('upload-ui');
        const controlsPanel = document.getElementById('controls-panel');
        const gridOverlay = document.getElementById('grid-overlay');
        const gainLabel = document.getElementById('gain-val');
        const loupe = document.getElementById('loupe');
        const container = document.getElementById('scan-container');
        const btnPeek = document.getElementById('btn-peek');
        let currentImage = null;
        let currentImageSrc = null;
        let currentMode = 'heat'; // 'heat', 'mono', 'edge'
        let isLoupeActive = false;
        function processSensorImage(input) {
            if (input.files && input.files[0]) {
                const reader = new FileReader();
                reader.onload = function (e) {
                    const img = new Image();
                    img.onload = function () {
                        currentImage = img;
                        currentImageSrc = e.target.result;
                        // Set canvas dimensions to match image to retain resolution
                        canvas.width = img.width;
                        canvas.height = img.height;
                        // Draw image to canvas
                        ctx.drawImage(img, 0, 0);
                        // Set loupe background
                        loupe.style.backgroundImage = `url('${currentImageSrc}')`;
                        // UI Transitions
                        uploadUI.classList.add('opacity-0');
                        setTimeout(() => {
                            uploadUI.style.display = 'none';
                            canvas.classList.remove('hidden');
                            controlsPanel.classList.remove('hidden');
                            controlsPanel.classList.add('flex');
                            updateFilter();
                            container.scrollIntoView({ behavior: 'smooth', block: 'center' });
                        }, 300);
                        // Reset Grid (prevent '1 2 3' from showing up prematurely)
                        document.getElementById('grid-toggle').checked = false;
                        gridOverlay.style.display = 'none';
                        gridOverlay.classList.add('hidden');
                    };
                    img.src = e.target.result;
                };
                reader.readAsDataURL(input.files[0]);
            }
        }
        function setMode(mode, btn) {
            currentMode = mode;
            // Button Styling Logic
            document.querySelectorAll('.segmented-control .chip').forEach(b => {
                b.classList.remove('chip-active');
                b.classList.add('chip-inactive');
            });
            btn.classList.add('chip-active');
            btn.classList.remove('chip-inactive');
            updateFilter();
        }
        function updateFilter() {
            if (!currentImage) return;
            const gain = document.getElementById('sensitivity').value;
            gainLabel.innerText = parseFloat(gain).toFixed(1) + 'x';
            // Apply selected algorithm via CSS filters
            let filterStr = "";
            if (currentMode === 'heat') {
                filterStr = `contrast(${gain}) brightness(0.7) hue-rotate(180deg) saturate(8)`;
            } else if (currentMode === 'mono') {
                filterStr = `contrast(${gain}) brightness(0.9) invert(1) grayscale(1)`;
            } else if (currentMode === 'edge') {
                filterStr = `contrast(${gain}) sepia(1) hue-rotate(90deg) saturate(10) invert(0.8)`;
            }
            canvas.style.filter = filterStr;
            // Apply identical filter to loupe to maintain visual consistency
            loupe.style.filter = filterStr;
        }
        function toggleGrid() {
            const isChecked = document.getElementById('grid-toggle').checked;
            if (isChecked) {
                gridOverlay.classList.remove('hidden');
                gridOverlay.style.display = 'grid';
            } else {
                gridOverlay.classList.add('hidden');
                gridOverlay.style.display = 'none';
            }
        }
        // --- DIGITAL LOUPE LOGIC ---
        function toggleLoupe() {
            isLoupeActive = document.getElementById('loupe-toggle').checked;
            if (!isLoupeActive) loupe.style.display = 'none';
        }
        container.addEventListener('mousemove', function (e) {
            if (!isLoupeActive || !currentImage) return;
            const rect = canvas.getBoundingClientRect();
            // Calculate cursor position relative to the canvas
            const x = e.clientX - rect.left;
            const y = e.clientY - rect.top;
            // Hide loupe if cursor leaves canvas bounds
            if (x < 0 || y < 0 || x > rect.width || y > rect.height) {
                loupe.style.display = 'none';
                return;
            }
            loupe.style.display = 'block';
            // Move loupe element (centered on cursor)
            loupe.style.left = (e.clientX - container.getBoundingClientRect().left - 80) + 'px';
            loupe.style.top = (e.clientY - container.getBoundingClientRect().top - 80) + 'px';
            // Calculate percentage position for background shifting
            const pctX = (x / rect.width) * 100;
            const pctY = (y / rect.height) * 100;
            // Set magnification zoom to exactly 300%
            loupe.style.backgroundSize = `${rect.width * 3}px ${rect.height * 3}px`;
            loupe.style.backgroundPosition = `${pctX}% ${pctY}%`;
        });
        container.addEventListener('mouseleave', function () {
            loupe.style.display = 'none';
        });
        // --- PEEK COMPARE LOGIC ---
        btnPeek.addEventListener('mousedown', () => { if (currentImage) canvas.style.filter = 'none'; });
        btnPeek.addEventListener('mouseup', updateFilter);
        btnPeek.addEventListener('mouseleave', updateFilter);
        btnPeek.addEventListener('touchstart', (e) => { e.preventDefault(); if (currentImage) canvas.style.filter = 'none'; });
        btnPeek.addEventListener('touchend', updateFilter);
        // --- HIGH-PERFORMANCE AUTO-SCAN ALGORITHM ---
        function runAutoScan() {
            if (!currentImage) return;
            const btn = document.getElementById('btn-autoscan');
            btn.innerHTML = '<span class="animate-pulse">SCANNING...</span>';
            btn.classList.add('opacity-50', 'pointer-events-none');
            // Short timeout allows browser to paint the 'SCANNING' text before blocking thread
            setTimeout(() => {
                try {
                    // Downscale image to max 1024px width for rapid scanning. 
                    // Reading 40-Megapixel images on the main thread will cause the browser to hang.
                    const MAX_WIDTH = 1024;
                    let scale = 1;
                    if (currentImage.width > MAX_WIDTH) {
                        scale = MAX_WIDTH / currentImage.width;
                    }
                    const scanW = Math.round(currentImage.width * scale);
                    const scanH = Math.round(currentImage.height * scale);
                    const tempCanvas = document.createElement('canvas');
                    tempCanvas.width = scanW;
                    tempCanvas.height = scanH;
                    const tempCtx = tempCanvas.getContext('2d', { willReadFrequently: true });
                    tempCtx.drawImage(currentImage, 0, 0, scanW, scanH);
                    const imgData = tempCtx.getImageData(0, 0, scanW, scanH);
                    const data = imgData.data;
                    let totalLuma = 0;
                    // 1. Calculate Average Luminance (Y = 0.299R + 0.587G + 0.114B)
                    for (let i = 0; i < data.length; i += 4) {
                        totalLuma += (data[i] * 0.299 + data[i + 1] * 0.587 + data[i + 2] * 0.114);
                    }
                    const avgLuma = totalLuma / (data.length / 4);
                    // 2. Set Threshold (Identify pixels that are 15% darker than the average background)
                    const threshold = avgLuma * 0.85;
                    let darkCount = 0;
                    // 3. Count "Dust" Pixels
                    for (let i = 0; i < data.length; i += 4) {
                        let luma = (data[i] * 0.299 + data[i + 1] * 0.587 + data[i + 2] * 0.114);
                        if (luma < threshold) darkCount++;
                    }
                    // 4. Calculate Final Score
                    const totalPixels = data.length / 4;
                    const dustPercentage = (darkCount / totalPixels) * 100;
                    // Algorithm scales harshly: even 1% dust coverage is a critically dirty sensor.
                    let healthScore = 100 - (dustPercentage * 200);
                    if (healthScore < 0) healthScore = 0;
                    if (healthScore > 100) healthScore = 100;
                    updateHealthWidget(Math.round(healthScore));
                } catch (e) {
                    console.error("Canvas read error:", e);
                    updateHealthWidget("ERR");
                }
                // Feedback UI Reset
                btn.innerHTML = 'SCAN COMPLETE';
                setTimeout(() => {
                    btn.innerHTML = 'RUN SCAN';
                    btn.classList.remove('opacity-50', 'pointer-events-none');
                }, 2000);
            }, 100);
        }
        // Updates BOTH the sidebar widget and the mobile-visible text area
        function updateHealthWidget(score) {
            const display = document.getElementById('health-score-display');
            const text = document.getElementById('health-score-text');
            const widget = document.getElementById('sidebar-health-widget');
            const mobileText = document.getElementById('mobile-scan-result');
            if (score === "ERR") {
                display.innerText = "ERR";
                text.innerText = "Local file restriction";
                mobileText.innerText = "File processing restricted";
                mobileText.className = "text-slate-400 text-[10px] mt-1 uppercase tracking-widest font-bold";
                return;
            }
            display.innerText = score + "/100";
            if (score >= 95) {
                text.innerText = "Sensor is clean";
                mobileText.innerText = `Score: ${score}/100 - Sensor is clean`;
                mobileText.className = "text-emerald-400 text-[10px] mt-1 uppercase tracking-widest font-bold";
                widget.className = "bg-emerald-900 rounded-3xl p-6 text-white shadow-xl border border-emerald-800 break-words transition-all duration-500";
                display.className = "text-4xl font-black tracking-tighter mb-1 text-emerald-400";
            } else if (score >= 70) {
                text.innerText = "Minor Dust Detected";
                mobileText.innerText = `Score: ${score}/100 - Minor Dust Detected`;
                mobileText.className = "text-yellow-400 text-[10px] mt-1 uppercase tracking-widest font-bold";
                widget.className = "bg-yellow-900 rounded-3xl p-6 text-white shadow-xl border border-yellow-800 break-words transition-all duration-500";
                display.className = "text-4xl font-black tracking-tighter mb-1 text-yellow-400";
            } else {
                text.innerText = "Cleaning Recommended";
                mobileText.innerText = `Score: ${score}/100 - Cleaning Recommended`;
                mobileText.className = "text-red-400 text-[10px] mt-1 uppercase tracking-widest font-bold";
                widget.className = "bg-red-900 rounded-3xl p-6 text-white shadow-xl border border-red-800 break-words transition-all duration-500";
                display.className = "text-4xl font-black tracking-tighter mb-1 text-red-400";
            }
        }
        function downloadDiagnostic() {
            if (!currentImage) return;
            const offCanvas = document.createElement('canvas');
            offCanvas.width = canvas.width;
            offCanvas.height = canvas.height;
            const offCtx = offCanvas.getContext('2d');
            offCtx.filter = canvas.style.filter;
            offCtx.drawImage(currentImage, 0, 0);
            // Draw Grid Lines if active
            if (document.getElementById('grid-toggle').checked) {
                offCtx.strokeStyle = "rgba(239, 68, 68, 0.8)";
                offCtx.lineWidth = Math.max(2, canvas.width / 500);
                const w3 = offCanvas.width / 3;
                const h3 = offCanvas.height / 3;
                offCtx.beginPath();
                offCtx.moveTo(w3, 0); offCtx.lineTo(w3, offCanvas.height);
                offCtx.moveTo(w3 * 2, 0); offCtx.lineTo(w3 * 2, offCanvas.height);
                offCtx.moveTo(0, h3); offCtx.lineTo(offCanvas.width, h3);
                offCtx.moveTo(0, h3 * 2); offCtx.lineTo(offCanvas.width, h3 * 2);
                offCtx.stroke();
            }
            const link = document.createElement('a');
            link.download = 'sensor-diagnostic-report.jpg';
            link.href = offCanvas.toDataURL('image/jpeg', 0.9);
            link.click();
        }
        function copyLink() {
            navigator.clipboard.writeText(window.location.href);
            alert('Link copied to clipboard!');
        }
        function shareLink(platform) {
            const url = encodeURIComponent(window.location.href);
            const text = encodeURIComponent("Check your camera sensor for dust with this free visualizer!");
            if (platform === 'wa') window.open(`https://wa.me/?text=${text}%20${url}`);
            if (platform === 'tw') window.open(`https://twitter.com/intent/tweet?text=${text}&url=${url}`);
        }
